    INSERT INTO tb_logs (table_name, table_operation, db_user, operation_date, operation_description, operation_status)
    VALUES ('tb_payments', 'Update', USER(), CURRENT_TIMESTAMP,
        CONCAT(
            'Modificación de Pago ID: ', OLD.ID,
            ' | ANTES -> ',
            'order_ID: ', IFNULL(OLD.order_ID, 'NULL'), ', ', 'payment_method_ID: ', IFNULL(OLD.payment_method_ID, 'NULL'), ', ', 'amount: ', IFNULL(OLD.amount, 'NULL'), ', ', 'payment_date: ', IFNULL(OLD.payment_date, 'NULL'), ', ', 'status: ', IFNULL(OLD.status+0, 'NULL'), ', ', 'creation_date: ', IFNULL(OLD.creation_date, 'NULL'), ', ', 'last_update: ', IFNULL(OLD.last_update, 'NULL'),
            ' | AHORA -> ',
            'order_ID: ', IFNULL(NEW.order_ID, 'NULL'), ', ', 'payment_method_ID: ', IFNULL(NEW.payment_method_ID, 'NULL'), ', ', 'amount: ', IFNULL(NEW.amount, 'NULL'), ', ', 'payment_date: ', IFNULL(NEW.payment_date, 'NULL'), ', ', 'status: ', IFNULL(NEW.status+0, 'NULL'), ', ', 'creation_date: ', IFNULL(NEW.creation_date, 'NULL'), ', ', 'last_update: ', IFNULL(NEW.last_update, 'NULL')
        ),
        b'1');
END */;;
