/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_payments_after_delete` AFTER DELETE ON `tb_payments` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (table_name, table_operation, db_user, operation_date, operation_description, operation_status)
    VALUES ('tb_payments', 'Delete', USER(), CURRENT_TIMESTAMP,
        CONCAT(
            'Baja de Pago ID: ', OLD.ID,
            ', order_ID: ', IFNULL(OLD.order_ID, 'NULL'),
            ', payment_method_ID: ', IFNULL(OLD.payment_method_ID, 'NULL'),
            ', amount: ', IFNULL(OLD.amount, 'NULL'),
            ', payment_date: ', IFNULL(OLD.payment_date, 'NULL'),
            ', status: ', IFNULL(OLD.status+0, 'NULL'),
            ', creation_date: ', IFNULL(OLD.creation_date, 'NULL'),
            ', last_update: ', IFNULL(OLD.last_update, 'NULL')
        ),
        b'1');
END */;;
