/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_people_after_insert` AFTER INSERT ON `tb_people` FOR EACH ROW BEGIN
    INSERT INTO tb_logs (
        table_name,
        table_operation,
        db_user,
        operation_date,
        operation_description,
        operation_status
    )
    VALUES (
        'tb_people',
        'Create',
        USER(),
        CURRENT_TIMESTAMP,
        CONCAT(
            'Persona registrada ID: ', NEW.person_ID,
            ', user_ID: ', NEW.user_ID,
            ', Nombre completo: ', COALESCE(NEW.courtesy_title, ''), ' ', NEW.given_names, ' ', NEW.family_names,
            ', Nacimiento: ', NEW.birth_date,
            ', Género: ', NEW.gender,
            ', Teléfono: (', NEW.country_code, ') ', NEW.phone,
            ', Status: ', NEW.status
        ),
        b'1'
    );
END */;;
DELIMITER ;
