DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sim_register_products_from_stage`()
BEGIN
    DECLARE v_db_user   VARCHAR(80);
    DECLARE v_has_role  INT DEFAULT 0;
    DECLARE v_row_id    INT UNSIGNED DEFAULT 0;
    DECLARE v_next      INT UNSIGNED;
    DECLARE v_msg       TEXT;
    DECLARE v_prod_id   INT UNSIGNED;
    DECLARE v_cat_id    INT UNSIGNED;
    DECLARE v_ok        INT DEFAULT 0;
    DECLARE v_err       INT DEFAULT 0;

    DECLARE v_sku       VARCHAR(50);
    DECLARE v_name      VARCHAR(250);
    DECLARE v_desc      TEXT;
    DECLARE v_price     DECIMAL(10,2);
    DECLARE v_stock     INT UNSIGNED;
    DECLARE v_category  VARCHAR(120);
    DECLARE v_status    TINYINT;

    -- Solo superadmin, admin, seller o support pueden simular productos
    SET v_db_user = SUBSTRING_INDEX(USER(), '@', 1);

    SELECT COUNT(*) INTO v_has_role
    FROM mysql.role_edges re
    WHERE re.TO_USER = v_db_user
      AND re.TO_HOST = '%'
      AND re.FROM_HOST = '%'
      AND re.FROM_USER IN ('superadmin', 'admin', 'seller', 'support');

    IF v_has_role = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Acceso denegado: rol no autorizado para simular productos';
    END IF;

    main_loop: LOOP
        SELECT MIN(row_id) INTO v_next
        FROM `db_test_7b_stage`.`tmp_products_import`
        WHERE processed = 0 AND row_id > v_row_id;

        IF v_next IS NULL THEN
            LEAVE main_loop;
        END IF;
        SET v_row_id = v_next;

        SELECT SKU, name, description, current_price, current_stock, category, status
        INTO   v_sku, v_name, v_desc, v_price, v_stock, v_category, v_status
        FROM `db_test_7b_stage`.`tmp_products_import`
        WHERE row_id = v_row_id;

        BEGIN
            DECLARE EXIT HANDLER FOR SQLEXCEPTION
            BEGIN
                GET DIAGNOSTICS CONDITION 1 v_msg = MESSAGE_TEXT;
                ROLLBACK;
                UPDATE `db_test_7b_stage`.`tmp_products_import`
                   SET processed = 2, error_msg = LEFT(v_msg, 255)
                 WHERE row_id = v_row_id;
                SET v_err = v_err + 1;
            END;

            SET v_cat_id = NULL;
            SELECT ID INTO v_cat_id FROM tbc_categories WHERE name = TRIM(v_category) LIMIT 1;
            IF v_cat_id IS NULL THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La categoría no existe en tbc_categories';
            END IF;

            START TRANSACTION;

            INSERT INTO tb_products (SKU, name, description, current_price, current_stock, status)
            VALUES (TRIM(v_sku), TRIM(v_name), v_desc, v_price, v_stock, v_status);

            SET v_prod_id = LAST_INSERT_ID();

            INSERT INTO tbd_products_categories (product_ID, category_ID, status)
            VALUES (v_prod_id, v_cat_id, v_status);

            COMMIT;

            UPDATE `db_test_7b_stage`.`tmp_products_import`
               SET processed = 1
             WHERE row_id = v_row_id;
            SET v_ok = v_ok + 1;
        END;
    END LOOP main_loop;

    SELECT v_ok AS registrados,
           v_err AS con_error,
           (SELECT COUNT(*) FROM tb_products) AS total_productos_en_la_base,
           v_db_user AS ejecutado_por;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
