CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_sim_register_users_from_stage`()
BEGIN
    DECLARE v_db_user   VARCHAR(80);
    DECLARE v_has_role  INT DEFAULT 0;
    DECLARE v_row_id    INT UNSIGNED DEFAULT 0;
    DECLARE v_next      INT UNSIGNED;
    DECLARE v_msg       TEXT;
    DECLARE v_user_id   INT UNSIGNED;
    DECLARE v_ok        INT DEFAULT 0;
    DECLARE v_err       INT DEFAULT 0;

    DECLARE v_email     VARCHAR(100);
    DECLARE v_nick      VARCHAR(50);
    DECLARE v_pass      VARCHAR(255);
    DECLARE v_title     VARCHAR(20);
    DECLARE v_given     VARCHAR(150);
    DECLARE v_family    VARCHAR(150);
    DECLARE v_birth     DATE;
    DECLARE v_gender    VARCHAR(30);
    DECLARE v_country   CHAR(2);
    DECLARE v_phone     VARCHAR(25);
    DECLARE v_status    TINYINT;

    -- Solo superadmin, admin o support pueden simular usuarios
    SET v_db_user = SUBSTRING_INDEX(USER(), '@', 1);

    SELECT COUNT(*) INTO v_has_role
    FROM mysql.role_edges re
    WHERE re.TO_USER = v_db_user
      AND re.TO_HOST = '%'
      AND re.FROM_HOST = '%'
      AND re.FROM_USER IN ('superadmin', 'admin', 'support');

    IF v_has_role = 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Acceso denegado: rol no autorizado para simular usuarios';
    END IF;

    main_loop: LOOP
        SELECT MIN(row_id) INTO v_next
        FROM `db_test_7b_stage`.`tmp_users_import`
        WHERE processed = 0 AND row_id > v_row_id;

        IF v_next IS NULL THEN
            LEAVE main_loop;
        END IF;
        SET v_row_id = v_next;

        SELECT email, nick, password, courtesy_title, given_names, family_names,
               birth_date, gender, country_code, phone, status
        INTO   v_email, v_nick, v_pass, v_title, v_given, v_family,
               v_birth, v_gender, v_country, v_phone, v_status
        FROM `db_test_7b_stage`.`tmp_users_import`
        WHERE row_id = v_row_id;

        BEGIN
            DECLARE EXIT HANDLER FOR SQLEXCEPTION
            BEGIN
                GET DIAGNOSTICS CONDITION 1 v_msg = MESSAGE_TEXT;
                ROLLBACK;
                UPDATE `db_test_7b_stage`.`tmp_users_import`
                   SET processed = 2, error_msg = LEFT(v_msg, 255)
                 WHERE row_id = v_row_id;
                SET v_err = v_err + 1;
            END;

            START TRANSACTION;

            INSERT INTO tb_users (email, nick, password, status)
            VALUES (LOWER(TRIM(v_email)), TRIM(v_nick), MD5(v_pass), v_status);

            SET v_user_id = LAST_INSERT_ID();

            INSERT INTO tb_people (
                user_ID, courtesy_title, given_names, family_names,
                birth_date, gender, country_code, phone, status
            )
            VALUES (
                v_user_id,
                NULLIF(TRIM(v_title), ''),
                TRIM(v_given),
                NULLIF(TRIM(v_family), ''),
                v_birth,
                v_gender,
                NULLIF(UPPER(TRIM(v_country)), ''),
                NULLIF(TRIM(v_phone), ''),
                v_status
            );

            COMMIT;

            UPDATE `db_test_7b_stage`.`tmp_users_import`
               SET processed = 1
             WHERE row_id = v_row_id;
            SET v_ok = v_ok + 1;
        END;
    END LOOP main_loop;

    SELECT v_ok AS registrados,
           v_err AS con_error,
           (SELECT COUNT(*) FROM tb_users) AS total_usuarios_en_la_base,
           v_db_user AS ejecutado_por;
END ;;
DELIMITER ;
